// Package scaledderivationgraph provides an end-to-end demo for the scaled
// (phase-09) derivation graph, exercising a ~1 980-token derivation graph
// across four synthetic accounting datasets.
//
// Dataset summary (seed 42, generated by gen/gen.go):
//
//	payroll.csv   — 100 rows: employee_id,department,salary,bonus
//	expenses.csv  — 500 rows: expense_id,category,department,amount,date
//	revenue.csv   — 1200 rows: txn_id,product,region,amount
//	refunds.csv   — 80 rows: refund_id,product,region,amount
//
// Derivation graph (happy path):
//
//	total_salaries   = calc.sum(100 salary tokens minted from payroll)
//	total_bonuses    = calc.sum(100 bonus tokens minted from payroll)
//	total_payroll    = calc.add(total_salaries, total_bonuses)
//	total_expenses   = calc.sum(500 expense tokens)
//	total_opex       = calc.add(total_payroll, total_expenses)
//	gross_revenue    = calc.sum(1200 revenue tokens, in 2 batches of ≤1000)
//	total_refunds    = calc.sum(80 refund tokens)
//	net_revenue      = calc.subtract(gross_revenue, total_refunds)
//	operating_income = calc.subtract(net_revenue, total_opex)
//
// Leaf token count: 100 + 100 + 500 + 1200 + 80 = 1980.
//
// Note: the plan spec listed 1880 leaf tokens, treating payroll as 100 tokens.
// Because salary and bonus must be minted as separate read-mint operations
// (each read-mint call has exactly one output_path and therefore yields one
// token value), payroll contributes 200 tokens (100 salary + 100 bonus).
// The correct leaf count is 1980.  TestScaledFauxbooksLeafCount asserts 1980.
//
// Revenue has 1200 rows, which exceeds the CLI maxCalcInputs limit of 1000.
// calc-gross-revenue is therefore split into two batches:
//
//	gross_revenue_batch1 = calc.sum(revenue tokens 1..1000)
//	gross_revenue_batch2 = calc.sum(revenue tokens 1001..1200)
//	gross_revenue        = calc.add(gross_revenue_batch1, gross_revenue_batch2)
//
// This adds 2 intermediate tokens to the derivation graph but does not change
// the leaf count (the 1200 revenue tokens remain leaves).
//
// The contribution invariant (sum of leaf contributions == operating_income)
// still holds; trace.Trace resolves contributions through the intermediate
// batch nodes transparently.
package scaledderivationgraph_test

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gowebpki/jcs"
	"github.com/shopspring/decimal"

	"github.com/humzakhan/provenant/access/cli"
	"github.com/humzakhan/provenant/audit/pack"
	"github.com/humzakhan/provenant/audit/report"
	"github.com/humzakhan/provenant/examples/derivation-graph/internal/testsupport"
	kernel "github.com/humzakhan/provenant/kernel/public"
	"github.com/humzakhan/provenant/kernel/public/bundle"
	"github.com/humzakhan/provenant/kernel/public/trace"
)

// fixedScaledTime is the deterministic clock used for all CLI invocations.
var fixedScaledTime = time.Date(2026, 1, 15, 9, 0, 0, 0, time.UTC)

// scaledRun is the fixed run identity for the scaled demo.
var scaledRun = kernel.Run{
	ID:       "derivation_graph_scaled_run_1",
	TenantID: "tenant_demo",
	Status:   kernel.RunRunning,
}

// dataDir is the path to the committed CSV source files relative to this package.
const dataDir = "data"

// ---------------------------------------------------------------------------
// TestScaledFauxbooksEndToEnd: full pipeline, golden assertions
// ---------------------------------------------------------------------------

func TestScaledFauxbooksEndToEnd(t *testing.T) {
	dir := t.TempDir()
	bundlePath := filepath.Join(dir, "scaled.bundle.json")

	runner := cli.Runner{Now: func() time.Time { return fixedScaledTime }}

	tids := runScaledDemo(t, runner, bundlePath)

	// Assert bundle bytes match golden.
	got, err := os.ReadFile(bundlePath)
	if err != nil {
		t.Fatalf("ReadFile(bundle): %v", err)
	}

	goldenPath := filepath.Join(".", "golden.bundle.json")
	if os.Getenv("UPDATE_GOLDEN") != "" {
		if err2 := os.WriteFile(goldenPath, got, 0o644); err2 != nil {
			t.Fatalf("write golden.bundle.json: %v", err2)
		}
		t.Logf("golden.bundle.json written (%d bytes)", len(got))
	}
	want, readErr := os.ReadFile(goldenPath)
	if readErr != nil {
		t.Fatalf("golden.bundle.json missing — run with UPDATE_GOLDEN=1 to generate: %v", readErr)
	}
	if !bytes.Equal(got, want) {
		t.Fatal("bundle bytes diverged from golden.bundle.json — if intentional, re-run with UPDATE_GOLDEN=1")
	}

	// Assert bundle.Verify.
	if err := bundle.Verify(got); err != nil {
		t.Fatalf("bundle.Verify: %v", err)
	}

	// Assert bundle.Replay.
	state, err := bundle.Replay(got)
	if err != nil {
		t.Fatalf("bundle.Replay: %v", err)
	}

	// Trace operating_income and assert golden trace.
	g, err := trace.Trace(got, tids.operatingIncome)
	if err != nil {
		t.Fatalf("trace.Trace: %v", err)
	}

	raw, err := json.Marshal(g)
	if err != nil {
		t.Fatalf("json.Marshal(graph): %v", err)
	}
	canonical, err := jcs.Transform(raw)
	if err != nil {
		t.Fatalf("jcs.Transform(graph): %v", err)
	}
	canonical = append(canonical, '\n')

	goldenTracePath := filepath.Join(".", "golden.trace.json")
	if os.Getenv("UPDATE_GOLDEN") != "" {
		if err2 := os.WriteFile(goldenTracePath, canonical, 0o644); err2 != nil {
			t.Fatalf("write golden.trace.json: %v", err2)
		}
		t.Logf("golden.trace.json written (%d bytes)", len(canonical))
	}
	wantTrace, readTraceErr := os.ReadFile(goldenTracePath)
	if readTraceErr != nil {
		t.Fatalf("golden.trace.json missing — run with UPDATE_GOLDEN=1 to generate: %v", readTraceErr)
	}
	if !bytes.Equal(canonical, wantTrace) {
		t.Fatal("trace JSON diverged from golden.trace.json — if intentional, re-run with UPDATE_GOLDEN=1")
	}

	// Contribution invariant: sum(leaf contributions) == operating_income value.
	opIncomeValue := ""
	for _, tok := range state.Tokens {
		if tok.ID == tids.operatingIncome {
			opIncomeValue = tok.ValueCanonical
			break
		}
	}
	if opIncomeValue == "" {
		t.Fatal("operating_income token not found in replayed state")
	}

	sum := decimal.Zero
	for _, lc := range g.Leaves {
		c, err := decimal.NewFromString(lc.Contribution)
		if err != nil {
			t.Fatalf("parse leaf contribution %q: %v", lc.Contribution, err)
		}
		sum = sum.Add(c)
	}
	opIncomeDec, err := decimal.NewFromString(opIncomeValue)
	if err != nil {
		t.Fatalf("parse operating_income value %q: %v", opIncomeValue, err)
	}
	if !sum.Equal(opIncomeDec) {
		t.Errorf("sum(contributions) = %s, want %s", sum.String(), opIncomeValue)
	}

	t.Logf("Operating Income: %s USD (leaf count: %d)", opIncomeValue, len(g.Leaves))
}

// ---------------------------------------------------------------------------
// TestScaledFauxbooksOperatingIncomeValue: independently verify the value
// ---------------------------------------------------------------------------

func TestScaledFauxbooksOperatingIncomeValue(t *testing.T) {
	dir := t.TempDir()
	bundlePath := filepath.Join(dir, "oi.bundle.json")
	runner := cli.Runner{Now: func() time.Time { return fixedScaledTime }}

	tids := runScaledDemo(t, runner, bundlePath)

	got, err := os.ReadFile(bundlePath)
	if err != nil {
		t.Fatalf("ReadFile(bundle): %v", err)
	}
	state, err := bundle.Replay(got)
	if err != nil {
		t.Fatalf("bundle.Replay: %v", err)
	}

	// Collect token values from state.
	tokensByID := make(map[string]string, len(state.Tokens))
	for _, tok := range state.Tokens {
		tokensByID[tok.ID] = tok.ValueCanonical
	}

	// Independently recompute operating_income from the CSV files.
	want := recomputeOperatingIncomeFromCSVs(t)

	// Read the token's ValueCanonical from the bundle.
	gotValue, ok := tokensByID[tids.operatingIncome]
	if !ok {
		t.Fatal("operating_income token not found in replayed state")
	}

	gotDec, err := decimal.NewFromString(gotValue)
	if err != nil {
		t.Fatalf("parse operating_income value %q: %v", gotValue, err)
	}
	if !gotDec.Equal(want) {
		t.Errorf("operating_income = %s, independently computed = %s", gotValue, want.String())
	}
}

// recomputeOperatingIncomeFromCSVs independently computes operating_income
// by summing columns directly from the CSV files, without using the kernel.
// This serves as an independent oracle for TestScaledFauxbooksOperatingIncomeValue.
func recomputeOperatingIncomeFromCSVs(t *testing.T) decimal.Decimal {
	t.Helper()

	totalSalaries := sumCSVColumn(t, filepath.Join(dataDir, "payroll.csv"), "salary")
	totalBonuses := sumCSVColumn(t, filepath.Join(dataDir, "payroll.csv"), "bonus")
	totalPayroll := totalSalaries.Add(totalBonuses)

	totalExpenses := sumCSVColumn(t, filepath.Join(dataDir, "expenses.csv"), "amount")
	totalOpex := totalPayroll.Add(totalExpenses)

	grossRevenue := sumCSVColumn(t, filepath.Join(dataDir, "revenue.csv"), "amount")
	totalRefunds := sumCSVColumn(t, filepath.Join(dataDir, "refunds.csv"), "amount")
	netRevenue := grossRevenue.Sub(totalRefunds)

	return netRevenue.Sub(totalOpex)
}

// sumCSVColumn reads a CSV file, finds the column header, and sums all values.
func sumCSVColumn(t *testing.T, path, header string) decimal.Decimal {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("ReadFile(%s): %v", path, err)
	}
	lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
	if len(lines) < 2 {
		t.Fatalf("CSV %s has no data rows", path)
	}
	// Parse header row.
	headers := strings.Split(lines[0], ",")
	colIdx := -1
	for i, h := range headers {
		if h == header {
			colIdx = i
			break
		}
	}
	if colIdx < 0 {
		t.Fatalf("CSV %s: column %q not found in headers %v", path, header, headers)
	}
	sum := decimal.Zero
	for i, line := range lines[1:] {
		if line == "" {
			continue
		}
		fields := strings.Split(line, ",")
		if colIdx >= len(fields) {
			t.Fatalf("CSV %s row %d: not enough columns", path, i+2)
		}
		d, err := decimal.NewFromString(fields[colIdx])
		if err != nil {
			t.Fatalf("CSV %s row %d col %s: parse %q: %v", path, i+2, header, fields[colIdx], err)
		}
		sum = sum.Add(d)
	}
	return sum
}

// ---------------------------------------------------------------------------
// TestScaledFauxbooksLeafCount: trace decomposes into exactly 1980 leaves
// ---------------------------------------------------------------------------

func TestScaledFauxbooksLeafCount(t *testing.T) {
	// Leaf count breakdown:
	//   payroll salary:  100 tokens (one per row, projecting salary column)
	//   payroll bonus:   100 tokens (one per row, projecting bonus column)
	//   expenses amount: 500 tokens
	//   revenue amount: 1200 tokens
	//   refunds amount:   80 tokens
	//   Total:          1980 leaf tokens
	//
	// Note: the plan spec listed 1880 (treating payroll as 100 tokens), but the
	// kernel requires one read-mint call per distinct (source, outputPath) pair,
	// so salary and bonus each need 100 mints.  See package doc for details.
	wantLeafCount := 1980

	dir := t.TempDir()
	bundlePath := filepath.Join(dir, "lc.bundle.json")
	runner := cli.Runner{Now: func() time.Time { return fixedScaledTime }}

	tids := runScaledDemo(t, runner, bundlePath)

	got, err := os.ReadFile(bundlePath)
	if err != nil {
		t.Fatalf("ReadFile(bundle): %v", err)
	}

	g, err := trace.Trace(got, tids.operatingIncome)
	if err != nil {
		t.Fatalf("trace.Trace: %v", err)
	}

	if lc := len(g.Leaves); lc != wantLeafCount {
		t.Errorf("leaf count = %d, want %d", lc, wantLeafCount)
	}
}

// ---------------------------------------------------------------------------
// TestScaledFauxbooksReplayDeterminism: two runs produce identical bundle bytes
// ---------------------------------------------------------------------------

func TestScaledFauxbooksReplayDeterminism(t *testing.T) {
	makeBundle := func(t *testing.T) []byte {
		t.Helper()
		dir := t.TempDir()
		bundlePath := filepath.Join(dir, "det.bundle.json")
		runner := cli.Runner{Now: func() time.Time { return fixedScaledTime }}
		runScaledDemo(t, runner, bundlePath)
		data, err := os.ReadFile(bundlePath)
		if err != nil {
			t.Fatalf("ReadFile(bundle): %v", err)
		}
		return data
	}

	b1 := makeBundle(t)
	b2 := makeBundle(t)
	if !bytes.Equal(b1, b2) {
		t.Fatal("two independent runs produced different bundle bytes — non-determinism bug")
	}
}

// ---------------------------------------------------------------------------
// TestScaledFauxbooksHTMLReport: audit-html renders a deterministic HTML report
// ---------------------------------------------------------------------------

func TestScaledFauxbooksHTMLReport(t *testing.T) {
	dir := t.TempDir()
	bundlePath := filepath.Join(dir, "scaled.bundle.json")
	packPath := filepath.Join(dir, "scaled.pack.json")
	htmlPath := filepath.Join(dir, "report.html")

	runner := cli.Runner{Now: func() time.Time { return fixedScaledTime }}
	runScaledDemo(t, runner, bundlePath)

	// Build the audit pack from the bundle.
	testsupport.RunCLIFileArgs(t, runner, []string{"pack", "--bundle", bundlePath, "--out", packPath})

	// Render the HTML report.
	testsupport.RunCLIFileArgs(t, runner, []string{"audit-html", "--pack", packPath, "--out", htmlPath})

	got, err := os.ReadFile(htmlPath)
	if err != nil {
		t.Fatalf("ReadFile(html): %v", err)
	}

	goldenPath := filepath.Join(".", "golden.report.html")
	if os.Getenv("UPDATE_GOLDEN") != "" {
		if err2 := os.WriteFile(goldenPath, got, 0o644); err2 != nil {
			t.Fatalf("write golden.report.html: %v", err2)
		}
		t.Logf("golden.report.html written (%d bytes)", len(got))
	}
	want, readErr := os.ReadFile(goldenPath)
	if readErr != nil {
		t.Fatalf("golden.report.html missing — run with UPDATE_GOLDEN=1 to generate: %v", readErr)
	}
	if !bytes.Equal(got, want) {
		t.Fatal("HTML report bytes diverged from golden.report.html — if intentional, re-run with UPDATE_GOLDEN=1")
	}
}

// ---------------------------------------------------------------------------
// Demo driver
// ---------------------------------------------------------------------------

// scaledTokenIDs holds the IDs of the key derived tokens produced by the demo.
type scaledTokenIDs struct {
	totalSalaries      string
	totalBonuses       string
	totalPayroll       string
	totalExpenses      string
	totalOpex          string
	grossRevenueBatch1 string
	grossRevenueBatch2 string
	grossRevenue       string
	totalRefunds       string
	netRevenue         string
	operatingIncome    string
}

// runScaledDemo executes the full scaled derivation-graph CLI sequence and returns
// the IDs of the key derived tokens.  The bundlePath must be a non-existent file
// in a writable directory.
func runScaledDemo(t *testing.T, runner cli.Runner, bundlePath string) scaledTokenIDs {
	t.Helper()

	// 1. run start
	testsupport.RunCLIInTest(t, runner, []string{"run", "start", "--request", "-"}, map[string]any{
		"run":      scaledRun,
		"run_file": bundlePath,
	})

	// 2. Mint payroll salary tokens (100 rows, projecting "salary" column).
	salarySrc := loadCSVSource(t, "payroll.csv")
	salaryTokenIDs := mintScaledCSVRowTokens(t, runner, bundlePath, salarySrc, 100, "salary")

	// 3. Mint payroll bonus tokens (100 rows, projecting "bonus" column).
	bonusTokenIDs := mintScaledCSVRowTokens(t, runner, bundlePath, salarySrc, 100, "bonus")

	// 4. Mint expenses tokens (500 rows, projecting "amount" column).
	expensesSrc := loadCSVSource(t, "expenses.csv")
	expensesTokenIDs := mintScaledCSVRowTokens(t, runner, bundlePath, expensesSrc, 500, "amount")

	// 5. Mint revenue tokens (1200 rows, projecting "amount" column).
	revenueSrc := loadCSVSource(t, "revenue.csv")
	revenueTokenIDs := mintScaledCSVRowTokens(t, runner, bundlePath, revenueSrc, 1200, "amount")

	// 6. Mint refunds tokens (80 rows, projecting "amount" column).
	refundsSrc := loadCSVSource(t, "refunds.csv")
	refundsTokenIDs := mintScaledCSVRowTokens(t, runner, bundlePath, refundsSrc, 80, "amount")

	// 7. calc.sum: total_salaries = sum(100 salary tokens)
	totalSalariesID := testsupport.CalcSum(t, runner, bundlePath, salaryTokenIDs)

	// 8. calc.sum: total_bonuses = sum(100 bonus tokens)
	totalBonusesID := testsupport.CalcSum(t, runner, bundlePath, bonusTokenIDs)

	// 9. calc.add: total_payroll = total_salaries + total_bonuses
	totalPayrollID := testsupport.CalcAdd(t, runner, bundlePath, totalSalariesID, totalBonusesID)

	// 10. calc.sum: total_expenses = sum(500 expense tokens)
	totalExpensesID := testsupport.CalcSum(t, runner, bundlePath, expensesTokenIDs)

	// 11. calc.add: total_opex = total_payroll + total_expenses
	totalOpexID := testsupport.CalcAdd(t, runner, bundlePath, totalPayrollID, totalExpensesID)

	// 12. calc.sum: gross_revenue (batched — revenue has 1200 rows, exceeds maxCalcInputs=1000).
	// Batch 1: revenue rows 1..1000
	// Batch 2: revenue rows 1001..1200
	grossRevenueBatch1ID := testsupport.CalcSum(t, runner, bundlePath, revenueTokenIDs[:1000])
	grossRevenueBatch2ID := testsupport.CalcSum(t, runner, bundlePath, revenueTokenIDs[1000:])
	grossRevenueID := testsupport.CalcAdd(t, runner, bundlePath, grossRevenueBatch1ID, grossRevenueBatch2ID)

	// 13. calc.sum: total_refunds = sum(80 refund tokens)
	totalRefundsID := testsupport.CalcSum(t, runner, bundlePath, refundsTokenIDs)

	// 14. calc.subtract: net_revenue = gross_revenue - total_refunds
	netRevenueID := testsupport.CalcSubtract(t, runner, bundlePath, grossRevenueID, totalRefundsID)

	// 15. calc.subtract: operating_income = net_revenue - total_opex
	operatingIncomeID := testsupport.CalcSubtract(t, runner, bundlePath, netRevenueID, totalOpexID)

	// 16. submit-answer: label the operating_income token.
	testsupport.RunCLIInTest(t, runner, []string{"submit-answer", "--request", "-"}, map[string]any{
		"run_file": bundlePath,
		"token_id": operatingIncomeID,
		"label":    "operating_income",
	})

	// 17. run finish
	testsupport.RunCLIInTest(t, runner, []string{"run", "finish", "--request", "-"}, map[string]any{
		"run_file": bundlePath,
	})

	return scaledTokenIDs{
		totalSalaries:      totalSalariesID,
		totalBonuses:       totalBonusesID,
		totalPayroll:       totalPayrollID,
		totalExpenses:      totalExpensesID,
		totalOpex:          totalOpexID,
		grossRevenueBatch1: grossRevenueBatch1ID,
		grossRevenueBatch2: grossRevenueBatch2ID,
		grossRevenue:       grossRevenueID,
		totalRefunds:       totalRefundsID,
		netRevenue:         netRevenueID,
		operatingIncome:    operatingIncomeID,
	}
}

// loadCSVSource reads a CSV data file and returns a kernel.SourceBytes for it.
func loadCSVSource(t *testing.T, filename string) kernel.SourceBytes {
	t.Helper()
	path := filepath.Join(dataDir, filename)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("ReadFile(%s): %v", path, err)
	}
	return testsupport.SourceWithHash("fixture://"+filename, data)
}

// csvProjectedOutputPath for a single-column projection: the projected column
// is always at cells[0] in the output envelope.
const csvProjectedOutputPath = "/rows/0/cells/0/value"

// mintScaledCSVRowTokens mints one token per data row from the given source,
// projecting a single column.  Returns token IDs in row order.
func mintScaledCSVRowTokens(t *testing.T, runner cli.Runner, bundlePath string, src kernel.SourceBytes, rowCount int, columnName string) []string {
	t.Helper()
	return testsupport.MintCSVRowTokens(t, runner, bundlePath, src, scaledRun, rowCount, columnName, csvProjectedOutputPath)
}

// ---------------------------------------------------------------------------
// TestScaledFauxbooksArtifact: produce the committed artifact directory
// ---------------------------------------------------------------------------

// TestScaledFauxbooksArtifact builds the pack and writes report.html (with
// relative source hrefs) plus the four source CSVs into the artifact directory.
// Gated by BUILD_ARTIFACT=1 so it does not run on every CI invocation.
// This test does NOT diff against a golden — it just writes the artifact directory.
func TestScaledFauxbooksArtifact(t *testing.T) {
	if os.Getenv("BUILD_ARTIFACT") != "1" {
		t.Skip("set BUILD_ARTIFACT=1 to regenerate the artifact directory")
	}

	dir := t.TempDir()
	bundlePath := filepath.Join(dir, "scaled.bundle.json")
	packPath := filepath.Join(dir, "scaled.pack.json")

	runner := cli.Runner{Now: func() time.Time { return fixedScaledTime }}
	runScaledDemo(t, runner, bundlePath)

	// Build the pack.
	testsupport.RunCLIFileArgs(t, runner, []string{"pack", "--bundle", bundlePath, "--out", packPath})

	// Decode the pack into a Document.
	packFile, err := os.Open(packPath)
	if err != nil {
		t.Fatalf("Open(pack): %v", err)
	}
	doc, err := pack.Decode(packFile)
	packFile.Close()
	if err != nil {
		t.Fatalf("pack.Decode: %v", err)
	}

	// Artifact directory (committed to source).
	artifactDir := filepath.Join(".", "artifact")
	if err := os.MkdirAll(artifactDir, 0o755); err != nil {
		t.Fatalf("MkdirAll(artifact): %v", err)
	}

	// Copy the four source CSVs into the artifact directory.
	csvFiles := []string{"expenses.csv", "payroll.csv", "refunds.csv", "revenue.csv"}
	testsupport.CopyDataDirToArtifact(t, dataDir, artifactDir, csvFiles...)

	// Write report.html with relative source hrefs (filenames co-located with the report).
	if err := report.WriteArtifactReport(artifactDir, &doc); err != nil {
		t.Fatalf("WriteArtifactReport: %v", err)
	}

	t.Logf("artifact written to %s", artifactDir)
}
